/*
 * BLE5-Stack configuration normally generated by SysConfig (ti_ble_config.h).
 * Only the controller part is used: the Zephyr Bluetooth host runs on top.
 */

#ifndef TI_BLE_CONFIG_H_
#define TI_BLE_CONFIG_H_

#include <bcomdef.h>
#include <hci.h>
#include <ti_radio_config.h>

#ifdef CONFIG_BT_MAX_CONN
#define MAX_NUM_BLE_CONNS CONFIG_BT_MAX_CONN
#else
#define MAX_NUM_BLE_CONNS 1
#endif

/* Number and size of controller data buffers */
#define MAX_NUM_PDU  CONFIG_BT_TI_CC13XX_CC26XX_MAX_NUM_PDU
#define MAX_PDU_SIZE CONFIG_BT_TI_CC13XX_CC26XX_MAX_PDU_SIZE

#ifndef EXTENDED_STACK_SETTINGS
#define EXTENDED_STACK_SETTINGS 0x00
#endif

/* Bonds are kept by the Zephyr host; this only sizes the resolving list */
#define GAP_BONDINGS_MAX CONFIG_BT_TI_CC13XX_CC26XX_RL_SIZE
#define GAP_CHAR_CFG_MAX 4

/* RF front end of the 2.4 GHz path (differential, external bias) */
#define RF_FE_MODE_AND_BIAS (RF_FE_DIFFERENTIAL | RF_FE_EXT_BIAS)

#define DEFAULT_TX_POWER HCI_EXT_TX_POWER_0_DBM

#endif /* TI_BLE_CONFIG_H_ */
